$workspace = (Resolve-Path -LiteralPath 'E:\Projects\theitzy').Path
$targets = @(
  'data\tmp-outline-render.png',
  'data\tmp-playwright-test.html',
  'data\tmp-export-outline-test'
)
$removed = @()
foreach ($rel in $targets) {
  $path = Join-Path $workspace $rel
  $resolved = Resolve-Path -LiteralPath $path -ErrorAction SilentlyContinue
  if ($resolved -and $resolved.Path.StartsWith($workspace, [System.StringComparison]::OrdinalIgnoreCase)) {
    Remove-Item -LiteralPath $resolved.Path -Recurse -Force
    $removed += $resolved.Path
  }
}
[pscustomobject]@{ Removed = $removed } | ConvertTo-Json -Depth 3

$workspace = (Resolve-Path -LiteralPath 'E:\Projects\theitzy').Path
$targets = @()
$targets += Get-ChildItem -LiteralPath $workspace -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'tmp_export_*_check.jpg' }
$targets += Get-ChildItem -LiteralPath (Join-Path $workspace 'data\logs') -File -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'backfill-export-extras-*' }
$removed = @()
foreach ($item in $targets) {
  $resolved = Resolve-Path -LiteralPath $item.FullName -ErrorAction SilentlyContinue
  if ($resolved -and $resolved.Path.StartsWith($workspace, [System.StringComparison]::OrdinalIgnoreCase)) {
    Remove-Item -LiteralPath $resolved.Path -Force
    $removed += $resolved.Path
  }
}
[pscustomobject]@{ RemovedCount = $removed.Count; Removed = $removed } | ConvertTo-Json -Depth 4

